// Keep optional shutter audio failures from interrupting photo capture.
function skyPlayCameraShutter(sound) {
  const diagnostics = globalThis.SkyJobsDiagnostics;
  const log = (level, event, details) => {
    if (diagnostics) diagnostics.log(level, event, details);
    else if (level === "error" || level === "warn") {
      console.warn(`[sky_jobs_base][camera][${event}] ${JSON.stringify(details)}`);
    }
  };
  if (!sound) {
    log("warn", "camera.shutter_missing", { message: "Shutter audio element is not mounted. Photo capture will continue." });
    return;
  }
  const source = diagnostics ? diagnostics.sourceUrl(sound.currentSrc || sound.src) : sound.currentSrc || sound.src;
  const reportFailure = (error) => {
    log("error", "camera.shutter_failed", {
      source,
      name: error && error.name,
      message: error && error.message,
      mediaErrorCode: sound.error && sound.error.code,
      readyState: sound.readyState,
      networkState: sound.networkState,
      hint: "Check camera-sound.wav and the sounds entry in fxmanifest.lua. Photo capture will continue.",
    });
  };
  try {
    log("debug", "camera.shutter_requested", { source });
    sound.currentTime = 0;
    const playback = sound.play();
    if (playback && typeof playback.then === "function") {
      playback.then(() => {
        log("info", "camera.shutter_playing", { source, message: "Shutter playback started successfully." });
      }).catch(reportFailure);
    }
  } catch (error) {
    reportFailure(error);
  }
}

// Observe the existing NUI transport without changing requests or responses.
async function je(endpoint, data = {}, method = "POST", options = {}) {
  const diagnostics = globalThis.SkyJobsDiagnostics;
  if (!diagnostics) return skyJobsNuiRequest(endpoint, data, method, options);
  return diagnostics.traceRequest(endpoint, method, () =>
    skyJobsNuiRequest(endpoint, data, method, { ...options, logErrors: false })
  );
}
